def find_route(connections):
    start = 1  # Start with the smallest number for bus routes
    routes = {}

    # Try assigning bus routes to the first available city
    for i, (u, v) in enumerate(connections):
        if start not in routes:
            routes[start] = (u, v)
            break
        start += 1

    # If no bus route available, no solution
    if start > 1 and start >= 2:
        return "No"

    return "Y\n" + " ".join(map(str, range(start, 2 * start)))

