from heapq import heappop, heappush

def min_cost(schedule, cost):
    pq, time = [], 0
    total_cost = 0
    for friend in schedule:
        t, bring, cost_per_liter = friend
        while 0 < t < time or pq:
            drop, water_cost_per_min = heappop(pq)
            if water_cost_per_min > cost_per_liter:
                break
            water_cost_per_min -= cost_per_liter
            total_cost += time * water_cost_per_min
            heappush(pq, (drop, water_cost_per_min))
        else:
            total_cost += time * (bring // m)
            time += bring // m
        while time - m >= 0 < bring:
            t -= m
            heappush(pq, (bring, cost_per_liter))
        bring -= bring % m
    while pq:
        drop, cost_per_min = heappop(pq)
        total_cost += time * cost_per_min
    return total_cost

