    # Build graph for bus routes to find matching pairs
    boyraph = defaultdict(set)
    for u, v in roads_boblines:
        boyraph[u].add(v)
        boyraph[v].add(u)

    # Build graph for rail routes to find matching pairs
    linegraph = defaultdict(set)
    for u, v in roads_bobrail:
        linegraph[u].add(v)
        linegraph[v].add(u)

    # Find matching pairs for both networks
    n_pairs = defaultdict(set)
    for i in range(n):
        for j in boyraph[i]:
            if j in linegraph:
                n_pairs[i].add(tuple(sorted((i, j))))
            else:
                n_pairs[i].add(tuple(sorted((i, j+n))))

        for j in linegraph[i]:
            if j not in boyraph:
                n_pairs[i].add(tuple(sorted((i, j+n))))

    # Printer not allowed to change numbers
    used_bus, used_rail = {'/'} | set(n_pairs[1]), set()
    for i in range(2, n):
        f, b, r, dr = 1, -1, n-1, n
        for bus in n_pairs[i]:
            if bus[0] in used_bus and bus[1] in used_rail:
                if r < bus[1]:
                    r, b = r, bus[1]
                used_bus.remove(bus[0])
        for bus in n_pairs[i]:
            if bus[1] in used_bus and bus[0] in used_rail:
                if r < bus[0]:
                    r, b = r, bus[0]
                used_bus.remove(bus[1])
        if b < f:
            dr, b = dr, max(b, 1)
        if r < f:
            dr, r = dr, n-1
        if r < b:
            f, r = f, max(b, 1)
        used_rail = used_rail.union(linegraph[b])
        used_rail.discard(i+n)
        used_rail.discard(i+n+1)

    # Priniting
    if used_rail & used_bus:
        return 'No'
    mapping = {}
    for i in range(n):
        mapping[i] = used_rail - used_bus
    print('Yes')
    for j in mapping:
        print(mapping[j] + 1, end=' ')
    print()

