    bus_edges = sorted(bus_edges)
    rail_edges = sorted(rail_edges)

    if not bus_edges:
        if len(rail_edges) == n - 1:
            return "Yes\n" + " ".join(map(str, range(n + 1, 2 * n + 1)))
        else:
            return "No"

    if len(rail_edges) == 0:
        if bus_edges[0][0] != 1 or bus_edges[-1][1] != 2 * n:
            return "No"
        edges = []
        for edge in bus_edges:
            edges.append((edge[1], edge[0]))
        if edges != rail_edges:
            return "No"
        else:
            return "Yes\n" + " ".join(map(str, range(2, 2 * n + 1)))

    # Check for conflicts
    for edge in bus_edges:
        if edge in rail_edges or (2 * n, edge[1]) in rail_edges:
            return "No"

    # Compute the mapping
    bus_to_rail = defaultdict(int)
    for i in range(len(bus_edges)):
        if bus_edges[i][1] < rail_edges[0][0]:
            bus_to_rail[bus_edges[i]] = rail_edges[0]
            rail_edges.pop(0)
        elif bus_edges[i][1] > rail_edges[-1][1]:
            bus_to_rail[bus_edges[i]] = rail_edges[-1]
            rail_edges.pop()
        if len(rail_edges) == 0:
            break

    # Ensure no overlap in edges
    if bus_edges + [edge for edge in rail_edges if edge[0] == 2 * n] != bus_edges + [(edge[1], edge[0]) for edge in rail_edges]:
        return "No"

    output = "Yes\n"
    for i in range(n):
        output += str(bus_to_rail[bus_edges[i]] if i < len(bus_edges) else rail_edges[0])
        if i != n - 1:
            output += " "
    return output

