        return False
    if not graph[a] and not graph[b]:
        return False
    if not graph[a]:
        return False
    if not graph[b]:
        return True
    return True

def check_matrix(matrix):
    """Check if the current matrix represents connectivity with the given statements."""
    n = len(matrix)
    for i in range(n):
        edge_count = Counter(matrix[i])
        if 'O' in edge_count or 'X' in edge_count:
            if 'O' in edge_count:
                node1, node2 = ['O', node1, node2] if graph[node1][node2] in {'A', 'X'} else ['O', node1, node2]
            elif 'X' in edge_count:
                node1, node2 = edge_count.keys() if graph[node1][node2] == 'A' else [node1, node2]
            else:
                return False
    return True

def min_edges(graph):
    visited = set()
    edges = 0
    for node in range(len(graph)):
        if node not in visited:
            stack = [node]
            while stack:
                node = stack.pop()
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)
            edges += max(0, len(visited) - 1)
    return edges

def solve():
