import heapq

class WeightedGraph:
    def __init__(self, n):
        self.graph = defaultdict(lambda: defaultdict(lambda: float('inf')))
        self.n = n
        self.m = 0

    def add_edge(self, u, v, w):
        self.graph[u][v] = w
        self.graph[v][u] = w
        self.m += 1

    def dijkstra(self, src):
        dist = {i: float('inf') for i in range(1, self.n + 1)}
        dist[src] = 0
        priority_queue = [(0, src)]

        while priority_queue:
            curr_dist, curr_vertex = heapq.heappop(priority_queue)

            if curr_dist > dist[curr_vertex]:
                continue

            for neighbor, weight in self.graph[curr_vertex].items():
                new_dist = curr_dist + weight
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(priority_queue, (new_dist, neighbor))

        return dist

