def get_uniqueness_matrix(n: int) -> tuple:
    matrix = {'A,': '00', 'O,': '10', 'X,': '01', '0,': '-'}
    uniqueness_matrix = dict()
    for u in range(n):
        for v in range(n):
            if matrix.get('A,') == '-' and matrix.get('O,') == '-' and matrix.get('X,') == '-':
                row = [0, 1, 0]
                row[u] = 1
                row[v] = 1
                row[n+u] = 1
                row[n+v] = 1
                identity = tuple(row)
                if (u, v) not in uniqueness_matrix:
                    uniqueness_matrix[tuple([u, v])] = tuple([0] * n)
                if (v, u) not in uniqueness_matrix:
                    uniqueness_matrix[tuple([v, u])] = tuple([0] * n)
                minim = tuple(range(n))
                minim[u], minim[v] = 1, 1
                minim[n+u], minim[n+v] = 1, 1
                minim[n+n+u], minim[n+n+v] = 1, 1
                row = min(identity, minim, key=identity.count)
                if row in uniqueness_matrix:
                    if identity == row:
                        uniqueness_matrix[tuple([u, v])] = 1
                    if minim == row:
                        uniqueness_matrix[tuple([v, u])] = 1
    return tuple([tuple(x) for x in uniqueness_matrix.values()])

