def recover_arrays(n, b_prime, c_prime):
    if len(b_prime) != n - 1 or len(c_prime) != n - 1:
        return -1

    max_sum = max(b_prime + c_prime)
    sum_values = set(b_prime + c_prime)

    min_val = min(sum_values)

    for x in sum_values:
        if len(bin(x - min_val)) // 4 > 3 * (n-1) - (n-2):
            return -1

    permutation = None

    def largest_pow2(v):
        p = 0
        while v > 0:
            v >>= 1
            p += 1
        return p

    for perm in range((1 << max(largest_pow2(x+2) if x > 0 else 1)) for x in sum_values):
        value_fn = BitMaskValueSelector(sum_values)
        if value_fn.evaluate(perm):
