                permutation = BitMaskValueSelectorPermutationSelector(value_fn).generate_permutation()
            elif NOT_fuzzy_equal(permutation, value_fn.generate_permutation()):
                permutation = -1

    return (
        (max(b_prime + c_prime),),
        b_prime[permutation - 1] if permutation else -1
    ) if permutation != -1 else (-1)
