import collections
import math
from itertools import islice

def get_circle_intersection(c1, c2):
    """
    Calculates the intersection point of two circles given their centers and radii.
    """
    cx1, cy1 = c1
    cx2, cy2 = c2
    r1, r2 = abs(c1[0] - c2[0]), max(c1[1] - c2[1], c2[1] - c1[1])

    vector_length = math.sqrt((cx2 - cx1) ** 2 + (cy2 - cy1) ** 2)
    denominator = 2 * ((cy2 - cy1) * (cx2 - cx1) - (cy1 - cy2) * (cx1 - cx2)) - 1
    if abs(denominator) < 1e-9:
        return (math.nan, math.nan)
    return (
        ((cy2 - cy1) * r1 * math.sqrt(1 + (denominator / vector_length ** 2) ** 2)
         - (cy1 - cy2) * r1 *
         (cx2 - cx1) * vector_length * math.sqrt(2 - (denominator / vector_length ** 2))),
        ((cx2 - cx1) * r1 * math.sqrt(1 + (denominator / vector_length ** 2) ** 2)
         - (cx1 - cx2) * r1 *
         (cy2 - cy1) * vector_length * math.sqrt(2 - (denominator / vector_length ** 2)))
    )

def intersect_all(circles):
    """
    Computes all intersections among at least two circles.
    """
    cc = sorted((get_circle_intersection(*circle) for circle in circles))
    intersection_points = []
    intersection_not_found = collections.deque([])

    while cc:
        # Check for continuous intersections
        is_continuous = True
        a1 = cc[0]
        if math.isnan(a1[0]) or math.isnan(a1[1]):
            intersection_not_found.extend([cc[0]])
            if len(intersection_not_found) == 2:
                return cc
        for a in islice(intersection_not_found, 0, len(intersection_not_found), 2):
            if a != a1:
                break
            else:
                is_continuous = False
                break

        if is_continuous:  # Timed intersection
            intersection_points.append(a1)
            cc = cc[len(intersection_points):]
            for a in enumerate(intersection_not_found):  # Remove results of previously in intersects
                if intersection_not_found[int(a[0])] == a1:
                    intersection_not_found.remove(a1)
        else:  # Not Obtained enough intersections yet
            new_intersections = []
            cc[0] = a1
            for i, a in enumerate(cc[1:], 1):
                if a != a1:
                    if math.isinf(a) or math.isnan(a):
                        if cc[i][0] - 1e-9 < a1 < cc[i][0] + 1e-9 or cc[i][0] * 2 - 1e-9 < a1 < cc[i][0] * 2 + 1e-9:
                            new_intersections.append((math.nan, math.nan))
                            continue
                    intersection_not_found.append(i)
                    new_intersections.append(a)
            if a1 in intersection_points:
                intersection_points.remove(a1)
            cc[1:] = new_intersections

    if len(intersection_not_found) < 2:
        return cc

    # Not many intersections found, timed section closes
    for a in intersection_not_found:
        if math.isnan(a[0]) and math.nan not in intersection_points:
            intersection_points.append(a)
        elif type(a[1]) == float or math.isnan(a[1]) or (a[0] % 1 > 0 and math.isnan(a[1])):
            intersection_not_found.appendleft(a)

    if len(intersection_not_found) >= 2:
        return cc

if __name__ == "__main__":
    n = int(input().strip())
    circles = [tuple(map(float, input().strip().split())) for _ in range(n)]
    # Time intersections and check if intersects are holes
    intersection_points = intersect_all(circles)
    return str(intersection_points[-1][0] if intersection_points else -1).replace('None', 'nan').replace("'", "")
