import sys

def min_operations(scores, demands):
    """
    Calculates the minimum number of operations required to satisfy all demands.
    """
    n = len(scores)
    demands_map = {i: (scores[i], None) for i in range(n)}

    for u, v in demands:
        if demands_map[u][0] <= demands_map[v][0]:
            demands_map[u] = (1, v)
            demands_map[v] = (0, None)
        else:
            demands_map[v] = (1, u)
            demands_map[u] = (0, None)

    cost = 0
    for i in range(n):
        if (1, i) in demands_map:
            cost += 1
        elif demands_map[i][0] == 1:
            cost += 1

    return cost

