def next_smaller(s):
    chars = list(s)
    for i in range(1, len(chars)):
        if chars[i-1] > chars[i]:
            break
    else:
        return s

    for j in range(i+1, len(chars)):
        if chars[j-1] < chars[i]:
            continue

        chars[i-1], chars[j] = chars[j], chars[i-1]
        for next_small in chars[i:]:
            if next_small > chars[i-1]:
                chars[i-1], next_small = next_small, chars[i-1]
        chars[i:] = sorted(chars[i:])
        break

    return ''.join(chars)

