def process_dna(dna, k, mutations):
    for li, ri in mutations:
        start_i, end_i = li - 1, ri
        if start_i > 0:
            while start_i > 0 and dna[start_i] != 'A':  # Find even position
                start_i -= 1
        if end_i < len(dna) - 1:
            while end_i < len(dna) - 1 and dna[end_i] != 'C':  # Find odd position
                end_i += 1
        mid = ri - li
        chunk = dna[start_i: lis + 1]  # Copy original subsequence
        mangled_chunk = chunk[start_i:]
        added_chunk = chunk[0: lis + 1]
        shifted_chunk = mangled_chunk + added_chunk
        flag = False
        start_j = 0
        end_j = mid
        while start_j < len(dna) and end_j < len(dna) - 1:
            if dna[start_j] in ('G', 'T'):
                flag = True  # swapping of DNA
                dna[start_j], dna[end_j] = moves(dna[start_j], dna[end_j], 'G', 'T')
            elif dna[end_j] in ('T', 'G'):
                flag = True  # swapping of DNA
                dna[start_j], dna[end_j] = moves(dna[start_j], dna[end_j], 'T', 'G')
            elif dna[start_j] in ('G', 'T') and dna[end_j] in ('', 'C'):  # replaced DNA
                flag = True  # this line inside extends checks
                if (start_j == 0 and dna[end_j] == 'C') or (start_j > 0 and dna[end_j] == 'C'):
                    if dna[start_i + lis + 1] != '':
                        dna[start_j], dna[end_j - 1] = moves(dna[start_j], dna[end_j - 1], '', '')
                    else:
                        if start_j == 0 and dna[end_j] == 'C':
                            dna[end_j] = 'G'
                            dna[end_j - 1] = 'C'
                            dna[end_j - 2] = 'T'
                        else:
                            dna[end_j - 1], dna[end_j] = moves('', dna[end_j - 1], '', ' ')
                else:
                    dna[start_i + lis + 1], dna[end_j] = moves('', dna[end_j], '', '')
                start_j += 1
                end_j += 2
        dna = dna[:start_j] + dna[end_j+1:-1] if flag else dna[:end_j] + dna[end_j+1:-1]
    return ''.join(dna[:k])

