from collections import defaultdict

mod = 998244353

def coinchange():
    n = int(input().strip())
    tree = defaultdict(list)
    for i in range(n-1):
        x, y = map(int, input().strip().split())
        tree[x].append(y)
        tree[y].append(x)

    color = [1] * (n+1)
    def htoff(k):
        def recur(s):
            if s == n:
                val.add((0,) * (k))
                return
            bag = tuple(color[x] - color[curr[1]] + mod - 1 for x in [0] + tree[curr[1]] if color[x] != curr[1])
            for v in val[bag]:
                if v > 0 and v < k and len(v) < k:
                    v.add(k)
                    recur(s + 1)
                    v.remove(k)
        val = set([(0,)])
        val.add(set())
        recur(0)
        return str(sum([len(v) for v in val.pop()]) % mod)

    return htoff(n)

print(int(coinchange()))

